  6	function escapeHtml(str) {
  7	  if (str === null || str === undefined) return '';
  8	  return String(str)
  9	    .replace(/&/g, '&amp;')
 10	    .replace(/</g, '&lt;')
 11	    .replace(/>/g, '&gt;')
 12	    .replace(/"/g, '&quot;');
 13	}
 14	
 15	function formatDate(isoString) {
 16	  if (!isoString) return '—';
 17	  try {
 18	    var d = new Date(isoString);
 19	    if (isNaN(d.getTime())) return escapeHtml(isoString);
 20	    var pad = function (n) { return String(n).padStart(2, '0'); };
 21	    var timeStr = pad(d.getHours()) + ':' + pad(d.getMinutes());
 22	
 23	    var now = new Date();
 24	    // Strip times for day-boundary comparisons
 25	    var today    = new Date(now.getFullYear(),    now.getMonth(),    now.getDate());
 26	    var itemDay  = new Date(d.getFullYear(),      d.getMonth(),      d.getDate());
 27	    var diffDays = Math.round((today - itemDay) / 86400000);
 28	
 29	    if (diffDays === 0) return 'Today, ' + timeStr;
 30	    if (diffDays === 1) return 'Yesterday, ' + timeStr;
 31	    var months = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
 32	    if (diffDays < 7)  return ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'][d.getDay()] + ', ' + d.getDate() + ' ' + months[d.getMonth()] + ', ' + timeStr;
 33	
 34	    // Older: show short date like "12 Feb 2026, 16:41"
 35	    return d.getDate() + ' ' + months[d.getMonth()] + ' ' + d.getFullYear() + ', ' + timeStr;
 36	  } catch (_) {
 37	    return escapeHtml(isoString);
 38	  }
 39	}
 40	
 41	function statusBadge(status) {
 42	  if (!status) return '';
 43	  var cls = 'badge badge-' + status.toLowerCase().replace(/_/g, '-');
 44	  return '<span class="' + cls + '">' + escapeHtml(status) + '</span>';
 45	}
 46	
 47	// Cache of namespaced key → display name, populated by views that fetch project data.
 48	// breadcrumb().project() reads from here automatically.
 49	// The cache key is the composite `repo + '/' + slug` to prevent collisions
 50	// between same-slug projects in different repositories.
 51	var ProjectNameCache = (function () {
 52	  var _cache = {};
 53	  return {
 54	    /**
 55	     * Store a display name for a project.
 56	     * @param {string} key  - Namespaced key in the form `repo/slug` (or bare slug for legacy callers).
 57	     * @param {string} name - Display name to cache.
 58	     */
 59	    set: function (key, name) {
 60	      if (key && name && name.trim()) _cache[key] = name.trim();
 61	    },
 62	    /**
 63	     * Retrieve the display name for a project.
 64	     * @param {string} key - Namespaced key in the form `repo/slug` (or bare slug for legacy callers).
 65	     * @returns {string} Cached display name, or the slug portion of the key if not found.
 66	     */
 67	    get: function (key) {
 68	      if (_cache[key]) return _cache[key];
 69	      // Fall back to the slug portion (after the last '/') so breadcrumbs show
 70	      // a readable label even before the project data is fetched.
 71	      var lastSlash = key ? key.lastIndexOf('/') : -1;
 72	      return lastSlash >= 0 ? key.slice(lastSlash + 1) : key;
 73	    },
 74	  };
 75	}());
 76	
 77	function breadcrumb() {
 78	  var segments = [];
 79	  var api = {
 80	    projects: function () {
 81	      segments.push({ label: 'Projects', href: '#/' });
 82	      return api;
 83	    },
 84	    project: function (repo, slug) {
 85	      segments.push({ label: ProjectNameCache.get(repo + '/' + slug), href: '#/projects/' + encodeURIComponent(repo) + '/' + encodeURIComponent(slug) });
 86	      return api;
 87	    },
 88	    leaf: function (label) {
 89	      segments.push({ label: label });
 90	      return api;
 91	    },
 92	    leafSpan: function (label, id) {
 93	      segments.push({ label: label, id: id });
 94	      return api;
 95	    },
 96	    html: function () {
 97	      return '<p class="breadcrumb">' +
 98	        segments.map(function (s) {
 99	          if (s.href) return '<a href="' + s.href + '">' + escapeHtml(s.label) + '</a>';
100	          if (s.id)   return '<span id="' + escapeHtml(s.id) + '">' + escapeHtml(s.label) + '</span>';

